7	/// `/vault` — the epic's one lock screen, shown whenever
8	/// `VaultRepository.currentStatus` isn't `VaultStatus.unlocked`
9	/// (`core/navigation/app_router.dart`'s `_redirect`). Auto-triggers the OS
10	/// biometric prompt once in [initState]; a successful
11	/// [VaultRepository.authenticate] call flips `currentStatus` to `unlocked`,
12	/// which — via `statusStream`/`refreshListenable` — re-runs the redirect and
13	/// navigates away from here on its own, so this widget never navigates
14	/// imperatively itself. No PIN entry UI (Story 2.2).
15	class VaultLockScreen extends StatefulWidget {
16	  const VaultLockScreen({required this.vaultRepository, super.key});
17	
18	  final VaultRepository vaultRepository;
19	
20	  @override
21	  State<VaultLockScreen> createState() => _VaultLockScreenState();
22	}
23	
24	class _VaultLockScreenState extends State<VaultLockScreen> {
25	  bool _authenticating = false;
26	  bool _showRetry = false;
27	
28	  @override
29	  void initState() {
30	    super.initState();
31	    _attemptAuthenticate();
32	  }
33	
34	  Future<void> _attemptAuthenticate() async {
35	    if (_authenticating) {
36	      return;
37	    }
38	    setState(() {
39	      _authenticating = true;
40	      _showRetry = false;
41	    });
42	
43	    final result = await widget.vaultRepository.authenticate();
44	    if (!mounted) {
45	      return;
46	    }
47	
48	    // On success, `currentStatus` is already `unlocked` and the router's
49	    // own `refreshListenable` will navigate away from `/vault` on its own —
50	    // this widget has nothing further to do (and may already be in the
51	    // process of being disposed by the time that happens).
52	    result.match(
53	      (_) => setState(() {
54	        _authenticating = false;
55	        _showRetry = true;
56	      }),
57	      (_) => setState(() {
58	        _authenticating = false;
59	      }),
60	    );
61	  }
62	
63	  @override
64	  Widget build(BuildContext context) {
65	    return Scaffold(
66	      backgroundColor: DesignTokens.colorSurfaceBg,
67	      body: Center(
68	        child: Padding(
69	          padding: DesignTokens.screenPadding,
70	          child: Column(
71	            mainAxisSize: MainAxisSize.min,
72	            children: [
73	              const Icon(
74	                Icons.lock_outline,
75	                size: DesignTokens.spacing2xl,
76	                color: DesignTokens.colorTextSecondary,
77	              ),
78	              const SizedBox(height: DesignTokens.spacingMd),
79	              Text(
80	                'Cerne bloqueado',
81	                textAlign: TextAlign.center,
82	                style: DesignTokens.textHeadlineMd.copyWith(
83	                  color: DesignTokens.colorTextPrimary,
84	                ),
85	              ),
86	              const SizedBox(height: DesignTokens.spacingSm),
87	              Text(
88	                'Use a biometria do seu dispositivo para continuar.',
89	                textAlign: TextAlign.center,
90	                style: DesignTokens.textBodyMd.copyWith(
91	                  color: DesignTokens.colorTextSecondary,
92	                ),
93	              ),
94	              if (_showRetry) ...[
95	                const SizedBox(height: DesignTokens.spacingLg),
96	                AppButton(
97	                  label: 'Tentar novamente',
98	                  onPressed: _attemptAuthenticate,
99	                ),
100	              ],
101	            ],
102	          ),
103	        ),
104	      ),
105	    );
106	  }
107	}
